using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.AspNetCore.Mvc.Rendering;using Microsoft.EntityFrameworkCore;using MYOB.Data;using MYOB.DTOs;using MYOB.Services;using MYOB.Support;
namespace MYOB.Pages.Operations.SupplierPayments;public class EditModel(ApplicationDbContext db,ITransactionService transactions,IPermissionService permissions):PageModel
{[BindProperty]public SupplierPaymentForm Item{get;set;}=null!;public SelectList Methods{get;private set;}=null!;public IReadOnlyList<PolicyOption> Policies{get;private set;}=[];public string SupplierName{get;private set;}="";public async Task<IActionResult> OnGetAsync(Guid id){if(!await permissions.HasAsync(User,ScreenCatalog.SupplierPayments,PermissionAction.Update))return Forbid();var x=await db.SupplierPayments.Include(x=>x.Supplier).AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id);if(x is null)return NotFound();Item=new(){Id=x.Id,SupplierId=x.SupplierId,SupplierReceiptId=x.SupplierReceiptId,Date=x.Date,Amount=x.Amount,PaymentMethodId=x.PaymentMethodId,Comments=x.Comments};SupplierName=x.Supplier.Name;await Load();return Page();}public async Task<IActionResult> OnPostAsync(){if(!await permissions.HasAsync(User,ScreenCatalog.SupplierPayments,PermissionAction.Update))return Forbid();if(ModelState.IsValid)try{await transactions.UpdateSupplierPaymentAsync(Item.Id,new(Item.SupplierId,Item.SupplierReceiptId,Item.Date,Item.Amount,Item.PaymentMethodId,Item.Comments));TempData["Message"]="تم تعديل حركة الدفع";return RedirectToPage("Index");}catch(InvalidOperationException e){ModelState.AddModelError(string.Empty,e.Message);}SupplierName=await db.Suppliers.Where(x=>x.Id==Item.SupplierId).Select(x=>x.Name).FirstOrDefaultAsync()??"";await Load();return Page();}private async Task Load(){Methods=new(await db.PaymentMethods.AsNoTracking().OrderBy(x=>x.Name).ToListAsync(),"Id","Name");Policies=await transactions.GetSupplierPoliciesAsync(Item.SupplierId,Item.Id);}}
